import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { ArrowLeft, Plus, Sparkles } from "lucide-react";
import { groupThemes } from "../../data/groups";

const kinds = [
  { id: "hostel", title: "Hostel", hint: "Rent and food", meta: "Hostel" },
  { id: "class", title: "Class", hint: "Notes and events", meta: "Classmates" },
  { id: "trip", title: "Trip", hint: "Plan together", meta: "College trip" },
];

function CreateGroup({ onCreate }) {
  const navigate = useNavigate();
  const [name, setName] = useState("");
  const [kind, setKind] = useState("hostel");
  const [theme, setTheme] = useState("green");

  const handleSubmit = (e) => {
    e.preventDefault();
    const trimmed = name.trim();
    if (!trimmed) return;

    const selectedKind = kinds.find((k) => k.id === kind);
    onCreate({
      id: Date.now(),
      name: trimmed,
      meta: `${selectedKind.meta} • 1 person`,
      balance: 0,
      theme,
      members: ["KS"],
    });
    navigate("/groups");
  };

  const labelClass =
    "block font-mono text-xs tracking-widest uppercase text-slate-500 mb-4";

  return (
    <div className="min-w-[760px] px-14 py-10">
      <div className="max-w-2xl mx-auto">
        <Link
          to="/groups"
          className="inline-flex items-center gap-3 font-semibold text-slate-500 hover:text-ink transition-colors"
        >
          <ArrowLeft size={20} />
          Back to groups
        </Link>

        <p className="mt-12 font-mono text-xs tracking-widest uppercase text-brand">
          College project
        </p>
        <h1 className="mt-3 text-6xl font-bold tracking-tight">
          Start a new group
        </h1>
        <p className="mt-4 text-lg text-slate-500">
          Create a shared space for your classmates, flatmates, or friends.
        </p>

        <form
          onSubmit={handleSubmit}
          className="mt-10 rounded-[2rem] bg-white border border-slate-200 p-10"
        >
          {/* Name */}
          <label htmlFor="groupName" className={labelClass}>
            Group name
          </label>
          <input
            id="groupName"
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. LD hostel room"
            className="w-full rounded-2xl border border-slate-200 bg-white px-5 py-4 text-lg outline-none transition placeholder:text-slate-400 focus:border-brand focus:ring-4 focus:ring-brand/15"
          />

          {/* Kind */}
          <p className={`${labelClass} mt-10`}>What kind of group?</p>
          <div className="grid grid-cols-3 gap-4">
            {kinds.map((k) => (
              <button
                key={k.id}
                type="button"
                onClick={() => setKind(k.id)}
                className={`text-left rounded-2xl border px-5 py-4 transition-colors ${
                  kind === k.id
                    ? "border-2 border-money bg-mint text-ink"
                    : "border-slate-200 bg-white text-slate-500 hover:border-slate-300"
                }`}
              >
                <p className="text-lg font-semibold">{k.title}</p>
                <p className="mt-1 text-sm">{k.hint}</p>
              </button>
            ))}
          </div>

          {/* Color */}
          <p className={`${labelClass} mt-10`}>Choose a group color</p>
          <div className="flex items-center gap-4">
            {Object.entries(groupThemes).map(([key, t]) => (
              <button
                key={key}
                type="button"
                onClick={() => setTheme(key)}
                aria-label={`${key} color`}
                className={`w-10 h-10 rounded-full transition ${t.swatch} ${
                  theme === key ? "ring-2 ring-ink ring-offset-2" : ""
                }`}
              />
            ))}
          </div>

          {/* Info */}
          <div className="mt-10 rounded-2xl bg-slate-50 px-6 py-5">
            <p className="flex items-center gap-2 font-semibold text-lg">
              <Sparkles size={20} className="text-brand" />
              Made for a college project
            </p>
            <p className="mt-2 text-slate-500">
              FairShare will suggest the simplest way to settle group costs.
            </p>
          </div>

          <button
            type="submit"
            disabled={!name.trim()}
            className="mt-8 w-full flex items-center justify-center gap-2 rounded-2xl py-4 text-lg font-semibold text-white bg-ink hover:bg-inkSoft transition-colors disabled:bg-slate-400 disabled:cursor-not-allowed"
          >
            <Plus size={20} />
            Create group
          </button>
        </form>
      </div>
    </div>
  );
}

export default CreateGroup;
